window.CALCULATORS=window.CALCULATORS||[];window.CALCULATORS.push(  {id:"loan-emi",slug:"loan-emi-calculator",title:"Loan EMI Calculator",category:"loan",short:"Calculate EMI and total interest for a standard loan.",desc:"A generic EMI calculator for personal, education, consumer or other fixed-rate amortizing loans.",article:{formula:"EMI = [P × r × (1+r)^n] ÷ [(1+r)^n − 1].",exampleInputs:{},faqs:[{q:"What loans can this model?",a:"It models standard fixed-rate amortizing loans; product-specific fees and changing rates are excluded."},{q:"Why compare total interest?",a:"Two loans with similar EMIs can have very different total costs because of rate and term."},{q:"Does this include processing fees?",a:"No. Add one-time fees separately."}]},fields:[{id:"principal",label:"Loan amount",type:"number",default:500000,min:0,max:1000,step:1},{id:"rate",label:"Annual interest rate",type:"number",default:12,min:0,max:60,step:1},{id:"years",label:"Repayment term",type:"number",default:5,min:1,max:30,step:1}],compute(v){const P=Math.max(v.principal,0),n=Math.max(1,Math.round(v.years*12)),r=Math.max(v.rate,0)/1200,emi=P===0?0:r===0?P/n:P*r*(1+r)**n/((1+r)**n-1),total=emi*n;return[{label:'Monthly EMI',value:emi,format:'currency',emphasis:'neutral'},{label:'Total repayment',value:total,format:'currency'},{label:'Total interest',value:total-P,format:'currency',emphasis:'negative'}];}});
